def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    jacket_patches = image_patch.find("blackjacket")
    skateboard_patches = image_patch.find("skateboard")

    if not man_patches or not jacket_patches or not skateboard_patches:
        return image_patch

    man_jacket_pairs = [(man, jacket) for man in man_patches for jacket in jacket_patches if distance_3d(man, jacket) < 0.5]
    man_skateboard_pairs = [(man, skateboard) for man in man_patches for skateboard in skateboard_patches if distance_3d(man, skateboard) < 0.5]

    valid_pairs = []
    for man, jacket in man_jacket_pairs:
        for man, skateboard in man_skateboard_pairs:
            if man == man_jacket_pairs[0][0] and man == man_skateboard_pairs[0][0]:
                valid_pairs.append((man, jacket, skateboard))

    if not valid_pairs:
        return image_patch

    return valid_pairs[0][0]

