def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    shirts = image_patch.find("shirt")
    shorts = image_patch.find("shorts")

    if not shirts or not shorts:
        return image_patch

    red_shirts = [shirt for shirt in shirts if shirt.verify_property("shirt", "red")]
    brown_shorts = [short for short in shorts if short.verify_property("shorts", "brown")]

    if not red_shirts or not brown_shorts:
        return image_patch

    red_shirt = red_shirts[0]
    brown_short = brown_shorts[0]

    if is_between_3d(red_shirt, brown_short, red_shirt):
        return red_shirt
    elif is_between_3d(brown_short, red_shirt, brown_short):
        return brown_short
    else:
        return red_shirt if red_shirt.horizontal_center < brown_short.horizontal_center else brown_short

