def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    guys = image_patch.find("guy")
    players = image_patch.find("player")

    if not guys or not players:
        return image_patch

    guy_centers = [(g.left + g.right) / 2 for g in guys]
    player_centers = [(p.left + p.right) / 2 for p in players]

    min_distance = float('inf')
    target_guy = None

    for i, guy_center in enumerate(guy_centers):
        for j, player_center in enumerate(player_centers):
            if abs(guy_center - player_center) < min_distance:
                min_distance = abs(guy_center - player_center)
                target_guy = guys[i]

    return target_guy

