def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people = image_patch.find("person")
    if not people: return image_patch

    # Sort people by their horizontal center
    people.sort(key=lambda p: p.horizontal_center)

    # Find the middle person
    mid_person = people[len(people) // 2]

    # Check if the knees are opposite
    opposite_knee_up = False
    for person in people:
        if person != mid_person:
            # Assuming the knee is near the center of the person's image
            if abs(person.horizontal_center - mid_person.horizontal_center) < mid_person.width / 4:
                opposite_knee_up = True
                break

    if opposite_knee_up:
        return mid_person
    else:
        return image_patch

def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    items = image_patch.find("item")  # Assuming "item" is a placeholder for the actual object names
    if len(items) < 3:
        return image_patch

    items.sort(key=lambda p: (p.vertical_center, p.horizontal_center))

    item1, item2, item3 = items[:3]

    if is_between_3d(item1, item2, item3):
        return item1
    elif is_between_3d(item2, item1, item3):
        return item2
    else:
        return item3

