def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    women = image_patch.find("woman")
    jackets = image_patch.find("jacket")

    if not women or not jackets:
        return image_patch

    white_jackets = [j for j in jackets if j.verify_property("jacket", "white")]
    gray_jackets = [j for j in jackets if j.verify_property("jacket", "gray")]

    if not white_jackets and not gray_jackets:
        return image_patch

    woman_with_white_jacket = None
    woman_with_gray_jacket = None

    for w in women:
        for j in white_jackets:
            if w.overlaps_with(j.left, j.lower, j.right, j.upper):
                woman_with_white_jacket = w
                break
        if woman_with_white_jacket:
            break

    for w in women:
        for j in gray_jackets:
            if w.overlaps_with(j.left, j.lower, j.right, j.upper):
                woman_with_gray_jacket = w
                break
        if woman_with_gray_jacket:
            break

    if woman_with_white_jacket and woman_with_gray_jacket:
        return depth_order([woman_with_white_jacket, woman_with_gray_jacket])[0]
    elif woman_with_white_jacket:
        return woman_with_white_jacket
    elif woman_with_gray_jacket:
        return woman_with_gray_jacket
    else:
        return image_patch

def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people = image_patch.find("person")
    if not people: return image_patch

    outfits = {}
    for person in people:
        color = person.best_text_match(["red", "blue", "green", "yellow", "black", "white"])
        if color not in outfits:
            outfits[color] = []
        outfits[color].append(person)

    if not outfits: return image_patch

    most_common_color = max(outfits, key=lambda k: len(outfits[k]))
    return depth_order(outfits[most_common_color])[0]

