def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    dog_patches = image_patch.find("dog")
    leg_patches = image_patch.find("leg")

    if not dog_patches or not leg_patches:
        return image_patch

    dogs_without_legs = []
    for dog in dog_patches:
        dog_center_x = (dog.left + dog.right) / 2
        dog_center_y = (dog.lower + dog.upper) / 2
        has_leg = any(
            abs(dog_center_x - leg.horizontal_center) < 10 and 
            abs(dog_center_y - leg.vertical_center) < 10
            for leg in leg_patches
        )
        if not has_leg:
            dogs_without_legs.append(dog)

    if not dogs_without_legs:
        return image_patch

    return depth_order(dogs_without_legs)[0]

