def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    boy_patches = image_patch.find("boy")
    suitcase_patches = image_patch.find("suitcase")

    if not boy_patches or not suitcase_patches:
        return image_patch

    boy_patches.sort(key=lambda p: p.horizontal_center)
    left_half = boy_patches[:max(1, len(boy_patches) // 2)]

    boy_on_suitcase = []
    for boy in left_half:
        for suitcase in suitcase_patches:
            if is_in_front_of(boy, suitcase):
                boy_on_suitcase.append((boy, suitcase))

    if not boy_on_suitcase:
        return boy_patches[0]

    boy_on_suitcase.sort(key=lambda x: distance(x[0], x[1]))
    return boy_on_suitcase[0][0]

def execute_command(image) -> ImagePatch:
