def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    shirt_patches = image_patch.find("shirt")
    skirt_patches = image_patch.find("skirt")

    if not shirt_patches or not skirt_patches:
        return image_patch

    shirt_depths = [(patch, patch.compute_depth()) for patch in shirt_patches]
    skirt_depths = [(patch, patch.compute_depth()) for patch in skirt_patches]

    shirt_closest = min(shirt_depths, key=lambda x: x[1])[0]
    skirt_closest = min(skirt_depths, key=lambda x: x[1])[0]

    if shirt_closest.overlaps_with(*skirt_closest.bbox()):
        return shirt_closest
    elif is_behind(shirt_closest, skirt_closest):
        return shirt_closest
    else:
        return skirt_closest

def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    arm_patches = image_patch.find("arm")
    if not arm_patches: 
        return image_patch

    # Sort arms based on their horizontal center
    arm_patches.sort(key=lambda p: p.horizontal_center)

    # Find the pair of arms that are closest together horizontally
    min_distance = float('inf')
    closest_pair = None
    for i in range(len(arm_patches)):
        for j in range(i + 1, len(arm_patches)):
            dist = abs(arm_patches[i].horizontal_center - arm_patches[j].horizontal_center)
            if dist < min_distance:
                min_distance = dist
                closest_pair = (arm_patches[i], arm_patches[j])

    # Check if the arms are crossed by comparing their vertical positions
    if closest_pair[0].vertical_center < closest_pair[1].vertical_center:
        return closest_pair[0]
    else:
        return closest_pair[1]

