def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    girl_patches = image_patch.find("girl")
    shirt_patches = image_patch.find("shirt")
    glasses_patches = image_patch.find("glasses")

    if not girl_patches or not shirt_patches or not glasses_patches:
        return image_patch

    girl_shirt_pairs = []
    for girl in girl_patches:
        for shirt in shirt_patches:
            if girl.overlaps_with(shirt.left, shirt.lower, shirt.right, shirt.upper):
                girl_shirt_pairs.append((girl, shirt))

    girl_shirt_glasses_triples = []
    for girl_shirt_pair in girl_shirt_pairs:
        girl, shirt = girl_shirt_pair
        for glasses in glasses_patches:
            if girl.overlaps_with(glasses.left, glasses.lower, glasses.right, glasses.upper):
                girl_shirt_glasses_triples.append((girl, shirt, glasses))

    if not girl_shirt_glasses_triples:
        return image_patch

    return depth_order([girl for girl, _, _ in girl_shirt_glasses_triples])[0]

