def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    shirts = image_patch.find("shirt")
    shorts = image_patch.find("shorts")

    if not shirts or not shorts:
        return image_patch

    blue_shirts = [shirt for shirt in shirts if shirt.verify_property("shirt", "blue")]
    tan_shorts = [short for short in shorts if short.verify_property("shorts", "tan")]

    if not blue_shirts or not tan_shorts:
        return image_patch

    blue_shirt = depth_order(blue_shirts)[0]
    tan_short = depth_order(tan_shorts)[0]

    if is_between_3d(blue_shirt, tan_short, blue_shirt):
        return blue_shirt
    elif is_between_3d(tan_short, blue_shirt, tan_short):
        return tan_short
    else:
        return blue_shirt if blue_shirt.compute_depth() < tan_short.compute_depth() else tan_short
